const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const basePremiumOf = (items: Item[]): number =>
  items.length * SWORD_BASE_PREMIUM;

const quote = (step: Step): QuoteResult => {
  const basePremium = basePremiumOf(step.items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;

  return { premium: basePremium + firstInsuranceSurcharge + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(quote),
});
